diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.stream.test.ts b/csv.stream.test.ts
--- a/csv.stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv.stream.test.ts	2026-10-29 14:40:10.494770035 +0000
@@ -0,0 +1,124 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function streamRows(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const chunk of chunks) rows.push(...s.push(chunk));
+  rows.push(...s.end());
+  return rows;
+}
+
+// The rows, or "Name: message" when the call throws, so both runs can be compared exactly.
+function outcome(f: () => string[][]): string[][] | string {
+  try {
+    return f();
+  } catch (e) {
+    return `${(e as Error).name}: ${(e as Error).message}`;
+  }
+}
+
+function rng(seed: number) {
+  return () => {
+    seed = (seed + 0x6d2b79f5) | 0;
+    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
+}
+
+test("a row comes back on the push that brings its row end, even when \\r and \\n are split", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\n")).toEqual([["a"]]);
+  expect(s.push("b,c\r\n")).toEqual([["b", "c"]]);
+});
+
+test("a \\r that is not followed by \\n is part of its field", () => {
+  expect(streamRows(["a\r", "b\n"])).toEqual([["a\rb"]]);
+  expect(streamRows(["a\r"])).toEqual([["a\r"]]);
+  expect(streamRows(["a\r\r\n"])).toEqual([["a\r"]]);
+});
+
+test("doubled quotes are one quote, also when the pair is split", () => {
+  expect(streamRows(['"x"', '"y"'])).toEqual([['x"y']]);
+  expect(streamRows(['"x"', '"', 'y"'])).toEqual([['x"y']]);
+  expect(streamRows(['"a,\r', '\nb"\n'])).toEqual([["a,\r\nb"]]);
+});
+
+test("text after a closing quote is a SyntaxError, also when split", () => {
+  expect(() => streamRows(['"a"b'])).toThrow(SyntaxError);
+  expect(() => streamRows(['"a"', "b"])).toThrow(SyntaxError);
+  expect(() => streamRows(['"a"\r', "x"])).toThrow(SyntaxError);
+  expect(() => streamRows(['"a"\r'])).toThrow(SyntaxError);
+});
+
+test("a quote in a field that is not quoted is a SyntaxError, also when split", () => {
+  expect(() => streamRows(["a", '"'])).toThrow(SyntaxError);
+  expect(() => streamRows(["a\r", '"'])).toThrow(SyntaxError);
+});
+
+test("a quoted field still open at the end is a SyntaxError", () => {
+  const s = new CsvStream();
+  expect(s.push('"ab')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a BOM is dropped only at the very start of the input", () => {
+  expect(streamRows(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(streamRows(["\uFEFF"])).toEqual([]);
+  expect(streamRows(["a\uFEFFb"])).toEqual([["a\uFEFFb"]]);
+});
+
+test("empty input has no rows, and a row end at the end adds no row", () => {
+  expect(streamRows([])).toEqual([]);
+  expect(streamRows(["", ""])).toEqual([]);
+  expect(streamRows(["a\n"])).toEqual([["a"]]);
+  expect(streamRows(["\n"])).toEqual([[""]]);
+  expect(streamRows(["a,"])).toEqual([["a", ""]]);
+});
+
+test("a stream agrees with parseCsv on random inputs and random splits, errors included", () => {
+  const random = rng(42);
+  const alphabet = ['a', ",", '"', "\r", "\n", "\uFEFF"];
+  for (let n = 0; n < 20000; n++) {
+    let text = "";
+    const len = Math.floor(random() * 13);
+    for (let k = 0; k < len; k++) text += alphabet[Math.floor(random() * alphabet.length)];
+    const splits: string[][] = [text.split("")];
+    for (let s = 0; s < 5; s++) {
+      const chunks: string[] = [];
+      let rest = text;
+      while (rest.length > 0 || random() < 0.2) {
+        const take = Math.floor(random() * 4);
+        chunks.push(rest.slice(0, take));
+        rest = rest.slice(take);
+        if (rest.length === 0 && random() < 0.5) break;
+      }
+      splits.push(chunks);
+    }
+    for (const chunks of splits) {
+      expect(outcome(() => streamRows(chunks))).toEqual(outcome(() => parseCsv(text)));
+    }
+  }
+});
+
+test("a stream over a 2 MB input in 3-character chunks gives parseCsv's rows", () => {
+  const text = `"${"x".repeat(1_000_000)}"\n` + "a,b,c\r\n".repeat(100_000);
+  const chunks: string[] = [];
+  for (let i = 0; i < text.length; i += 3) chunks.push(text.slice(i, i + 3));
+  expect(streamRows(chunks)).toEqual(parseCsv(text));
+});
+
+test("push and end after end() throw, and a failed stream keeps throwing", () => {
+  const done = new CsvStream();
+  done.push("a");
+  expect(done.end()).toEqual([["a"]]);
+  expect(() => done.push("b")).toThrow("CsvStream already ended");
+  expect(() => done.end()).toThrow("CsvStream already ended");
+
+  const failed = new CsvStream();
+  expect(() => failed.push('"a"b')).toThrow(SyntaxError);
+  expect(() => failed.push("c")).toThrow(SyntaxError);
+  expect(() => failed.end()).toThrow(SyntaxError);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 14:38:33.903791048 +0000
+++ b/csv.ts	2026-10-29 14:40:02.634769567 +0000
@@ -50,3 +50,111 @@
   rows.push(row);
   return rows;
 }
+
+type State = "fieldStart" | "unquoted" | "unquotedCr" | "quoted" | "quotedQuote" | "afterClose" | "afterCloseCr";
+
+/**
+ * parseCsv for input that arrives in chunks of any size: the rows from all calls together are parseCsv of the whole
+ * input, and each call does work in proportion to its own chunk. Errors are the ones parseCsv throws.
+ */
+export class CsvStream {
+  private state: State = "fieldStart";
+  private field = "";
+  private row: string[] = [];
+  private offset = 0;
+  private crAt = 0;
+  private ended = false;
+  private failed = false;
+
+  push(chunk: string): string[][] {
+    this.check();
+    const rows: string[][] = [];
+    try {
+      for (let i = 0; i < chunk.length; i++) this.char(chunk[i]!, this.offset++, rows);
+    } catch (e) {
+      this.failed = true;
+      throw e;
+    }
+    return rows;
+  }
+
+  end(): string[][] {
+    this.check();
+    const rows: string[][] = [];
+    try {
+      if (this.state === "quoted") throw new SyntaxError("a quoted field is still open at the end of the input");
+      if (this.state === "afterCloseCr") throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.crAt}`);
+      if (this.state === "unquotedCr") this.field += "\r";
+      if (this.state !== "fieldStart" || this.row.length > 0) this.endField(rows, true);
+    } catch (e) {
+      this.failed = true;
+      throw e;
+    }
+    this.ended = true;
+    return rows;
+  }
+
+  private check() {
+    if (this.ended) throw new Error("CsvStream already ended");
+    if (this.failed) throw new SyntaxError("stream failed earlier");
+  }
+
+  private char(c: string, at: number, rows: string[][]) {
+    if (at === 0 && c === "\uFEFF") return;
+    switch (this.state) {
+      case "fieldStart":
+        if (c === '"') this.state = "quoted";
+        else {
+          this.state = "unquoted";
+          this.char(c, at, rows);
+        }
+        return;
+      case "unquoted":
+        if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${at}`);
+        if (c === "\r") this.state = "unquotedCr";
+        else if (c === "," || c === "\n") this.endField(rows, c === "\n");
+        else this.field += c;
+        return;
+      case "unquotedCr":
+        if (c === "\n") return this.endField(rows, true);
+        this.field += "\r";
+        this.state = "unquoted";
+        this.char(c, at, rows);
+        return;
+      case "quoted":
+        if (c === '"') this.state = "quotedQuote";
+        else this.field += c;
+        return;
+      case "quotedQuote":
+        if (c === '"') {
+          this.field += '"';
+          this.state = "quoted";
+          return;
+        }
+        this.state = "afterClose";
+        this.char(c, at, rows);
+        return;
+      case "afterClose":
+        if (c === "\r") {
+          this.state = "afterCloseCr";
+          this.crAt = at;
+        } else if (c === "," || c === "\n") this.endField(rows, c === "\n");
+        else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${at}`);
+        return;
+      case "afterCloseCr":
+        if (c !== "\n") throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.crAt}`);
+        this.endField(rows, true);
+        return;
+    }
+  }
+
+  private endField(rows: string[][], rowEnd: boolean) {
+    this.row.push(this.field);
+    this.field = "";
+    this.state = "fieldStart";
+    if (rowEnd) {
+      rows.push(this.row);
+      this.row = [];
+    }
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.stream.test.ts b/csv.stream.test.ts
--- a/csv.stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv.stream.test.ts	2026-10-29 14:40:16.238770376 +0000
@@ -0,0 +1,170 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function viaStream(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const chunk of chunks) rows.push(...s.push(chunk));
+  rows.push(...s.end());
+  return rows;
+}
+
+function mulberry32(seed: number): () => number {
+  return () => {
+    seed = (seed + 0x6d2b79f5) | 0;
+    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
+}
+
+test("a comma separates fields and a row ends at a row end", () => {
+  expect(viaStream(["a,b\n"])).toEqual([["a", "b"]]);
+});
+
+test("a \\r \\n pair split across chunks is one row end", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.end()).toEqual([["b"]]);
+});
+
+test("a lone \\r is part of its field, also when it ends a chunk", () => {
+  expect(viaStream(["a\r", "b\n"])).toEqual([["a\rb"]]);
+  expect(viaStream(["a\r\r\n"])).toEqual([["a\r"]]);
+  expect(viaStream(["a\r"])).toEqual([["a\r"]]);
+});
+
+test("a doubled quote split across chunks is one quote", () => {
+  expect(viaStream(['"x"', '"y"\n'])).toEqual([['x"y']]);
+});
+
+test("a quoted field may hold separators and row ends split across chunks", () => {
+  const s = new CsvStream();
+  expect(s.push('"a\n')).toEqual([]);
+  expect(s.push('b"\n')).toEqual([["a\nb"]]);
+  expect(viaStream(['"a,', '\r', '"\n'])).toEqual([["a,\r"]]);
+});
+
+test("text after a closing quote is a SyntaxError, also a lone \\r", () => {
+  expect(() => viaStream(['"a"rx'])).toThrow(SyntaxError);
+  expect(() => viaStream(['"a"\rx'])).toThrow(SyntaxError);
+});
+
+test("a closing quote followed by a lone \\r waits, and end() throws", () => {
+  const s = new CsvStream();
+  expect(s.push('"a"\r')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a quote in an unquoted field is a SyntaxError", () => {
+  const s = new CsvStream();
+  expect(() => s.push('ab"')).toThrow(SyntaxError);
+});
+
+test("a quoted field still open at the end is a SyntaxError from end()", () => {
+  const s = new CsvStream();
+  expect(s.push('"ab')).toEqual([]);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("a BOM is dropped only at the very start of the input", () => {
+  expect(viaStream(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(viaStream(["a", "\uFEFF"])).toEqual([["a\uFEFF"]]);
+  expect(viaStream(["\uFEFF"])).toEqual([]);
+});
+
+test("the end of input ends the last row without starting another", () => {
+  const s = new CsvStream();
+  expect(s.push("a\n")).toEqual([["a"]]);
+  expect(s.end()).toEqual([]);
+  expect(viaStream(["a\r", "\n"])).toEqual([["a"]]);
+});
+
+test("empty input has no rows", () => {
+  expect(new CsvStream().end()).toEqual([]);
+  expect(viaStream([""])).toEqual([]);
+});
+
+test("an empty line is one empty field", () => {
+  expect(viaStream(["a\n\nb"])).toEqual([["a"], [""], ["b"]]);
+  expect(viaStream(["a,\n"])).toEqual([["a", ""]]);
+});
+
+test("after a SyntaxError every later call throws it again", () => {
+  const s = new CsvStream();
+  expect(() => s.push('a"')).toThrow(SyntaxError);
+  expect(() => s.push("b\n")).toThrow(SyntaxError);
+  expect(() => s.end()).toThrow(SyntaxError);
+});
+
+test("after end() every later call throws", () => {
+  const s = new CsvStream();
+  s.push("a\n");
+  s.end();
+  expect(() => s.push("b")).toThrow("CsvStream has ended");
+  expect(() => s.end()).toThrow("CsvStream has ended");
+});
+
+test("agrees with parseCsv for random inputs and random chunkings", () => {
+  const random = mulberry32(1);
+  const alphabet = ["a", ",", '"', "\r", "\n", "\uFEFF"];
+  const pick = () => alphabet[Math.floor(random() * alphabet.length)]!;
+  for (let n = 0; n < 3000; n++) {
+    let text = "";
+    const length = Math.floor(random() * 13);
+    for (let k = 0; k < length; k++) text += pick();
+    const splits = [[text], ["", ...text]];
+    for (let k = 0; k < 3; k++) {
+      const cuts = [0, 0, 0].map(() => Math.floor(random() * (text.length + 1))).sort((x, y) => x - y);
+      splits.push([text.slice(0, cuts[0]), text.slice(cuts[0], cuts[1]), text.slice(cuts[1], cuts[2]), text.slice(cuts[2])]);
+    }
+    for (const chunks of splits) {
+      let expected: string[][] | undefined;
+      try {
+        expected = parseCsv(text);
+      } catch (e) {
+        expect(e).toBeInstanceOf(SyntaxError);
+      }
+      if (expected === undefined) expect(() => viaStream(chunks)).toThrow(SyntaxError);
+      else expect(viaStream(chunks)).toEqual(expected);
+    }
+  }
+});
+
+test("agrees with parseCsv for every two-cut split of short inputs", () => {
+  const alphabet = ["a", ",", '"', "\r", "\n", "\uFEFF"];
+  const texts = [""];
+  for (let length = 1; length <= 4; length++) {
+    for (const prev of texts.filter((t) => t.length === length - 1)) {
+      for (const c of alphabet) texts.push(prev + c);
+    }
+  }
+  for (const text of texts) {
+    for (let a = 0; a <= text.length; a++) {
+      for (let b = a; b <= text.length; b++) {
+        const chunks = [text.slice(0, a), text.slice(a, b), text.slice(b)];
+        let expected: string[][] | undefined;
+        try {
+          expected = parseCsv(text);
+        } catch {
+          expected = undefined;
+        }
+        if (expected === undefined) expect(() => viaStream(chunks)).toThrow(SyntaxError);
+        else expect(viaStream(chunks)).toEqual(expected);
+      }
+    }
+  }
+});
+
+test("a large input pushed one character at a time matches parseCsv", () => {
+  let text = "";
+  for (let i = 0; text.length < 200_000; i++) {
+    text += i % 2 === 0 ? `${i},"q ""${i}""",x\r\n` : `plain${i},,y\n`;
+  }
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of text) rows.push(...s.push(c));
+  rows.push(...s.end());
+  expect(rows).toEqual(parseCsv(text));
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 14:38:33.911393153 +0000
+++ b/csv.ts	2026-10-29 14:39:57.118769240 +0000
@@ -50,3 +50,121 @@
   rows.push(row);
   return rows;
 }
+
+type StreamState = "fieldStart" | "unquoted" | "crUnquoted" | "quoted" | "quoteInQuoted" | "afterClose" | "crAfterClose";
+
+/** `parseCsv` for input that arrives in chunks: the same rows, returned as soon as they are complete. */
+export class CsvStream {
+  private row: string[] = [];
+  private field = "";
+  private state: StreamState = "fieldStart";
+  private offset = 0;
+  private error?: SyntaxError;
+  private ended = false;
+
+  push(chunk: string): string[][] {
+    this.check();
+    const rows: string[][] = [];
+    for (let k = 0; k < chunk.length; k++) this.feed(chunk[k]!, rows);
+    return rows;
+  }
+
+  end(): string[][] {
+    this.check();
+    const rows: string[][] = [];
+    switch (this.state) {
+      case "fieldStart":
+        if (this.row.length > 0) this.endRow(rows);
+        break;
+      case "unquoted":
+      case "quoteInQuoted":
+      case "afterClose":
+        this.endRow(rows);
+        break;
+      case "crUnquoted":
+        this.field += "\r";
+        this.endRow(rows);
+        break;
+      case "quoted":
+        this.fail("a quoted field is still open at the end of the input");
+      case "crAfterClose":
+        this.fail(`unexpected "\\r" after a closing quote at offset ${this.offset - 1}`);
+    }
+    this.ended = true;
+    return rows;
+  }
+
+  private check() {
+    if (this.error) throw this.error;
+    if (this.ended) throw new Error("CsvStream has ended");
+  }
+
+  private fail(message: string): never {
+    this.error = new SyntaxError(message);
+    throw this.error;
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+  }
+
+  private endRow(rows: string[][]) {
+    this.endField();
+    rows.push(this.row);
+    this.row = [];
+    this.state = "fieldStart";
+  }
+
+  private feed(c: string, rows: string[][]) {
+    const at = this.offset++;
+    if (at === 0 && c === "\uFEFF") return;
+    if (this.state === "crUnquoted") {
+      if (c === "\n") return this.endRow(rows);
+      this.field += "\r";
+      this.state = "unquoted";
+    }
+    if (this.state === "quoteInQuoted" && c !== '"') this.state = "afterClose";
+    switch (this.state) {
+      case "fieldStart":
+        if (c === '"') this.state = "quoted";
+        else if (c === "\r") this.state = "crUnquoted";
+        else if (c === "\n") this.endRow(rows);
+        else if (c === ",") this.endField();
+        else {
+          this.field = c;
+          this.state = "unquoted";
+        }
+        break;
+      case "unquoted":
+        if (c === ",") {
+          this.endField();
+          this.state = "fieldStart";
+        } else if (c === "\n") this.endRow(rows);
+        else if (c === "\r") this.state = "crUnquoted";
+        else if (c === '"') this.fail(`a quote in a field that is not quoted, at offset ${at}`);
+        else this.field += c;
+        break;
+      case "quoted":
+        if (c === '"') this.state = "quoteInQuoted";
+        else this.field += c;
+        break;
+      case "quoteInQuoted":
+        this.field += '"';
+        this.state = "quoted";
+        break;
+      case "afterClose":
+        if (c === ",") {
+          this.endField();
+          this.state = "fieldStart";
+        } else if (c === "\n") this.endRow(rows);
+        else if (c === "\r") this.state = "crAfterClose";
+        else this.fail(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${at}`);
+        break;
+      case "crAfterClose":
+        if (c === "\n") this.endRow(rows);
+        else this.fail(`unexpected "\\r" after a closing quote at offset ${at - 1}`);
+        break;
+    }
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv-stream.test.ts b/csv-stream.test.ts
--- a/csv-stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv-stream.test.ts	2026-10-29 14:42:35.194778636 +0000
@@ -0,0 +1,140 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function run(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const c of chunks) rows.push(...s.push(c));
+  rows.push(...s.end());
+  return rows;
+}
+
+function outcome(f: () => string[][]): { rows: string[][] } | { error: string } {
+  try {
+    return { rows: f() };
+  } catch (e) {
+    if (!(e instanceof SyntaxError)) throw e;
+    return { error: e.message };
+  }
+}
+
+test("a row end split between chunks is one row end", () => {
+  expect(run(["a\r", "\nb"])).toEqual([["a"], ["b"]]);
+});
+
+test("a lone \\r is part of its field, also at the end of the input", () => {
+  expect(run(["a\r"])).toEqual([["a\r"]]);
+  expect(run(["a\r", "b"])).toEqual([["a\rb"]]);
+});
+
+test("a doubled quote split between chunks is one quote", () => {
+  expect(run(['"x"', '"y"'])).toEqual([['x"y']]);
+});
+
+test("a quoted field may hold , \\r and \\n across chunks", () => {
+  expect(run(['"a,\r', '\nb"\n'])).toEqual([["a,\r\nb"]]);
+});
+
+test("text after a closing quote is an error, also in a later chunk", () => {
+  expect(() => run(['"a"', "b"])).toThrow(SyntaxError);
+});
+
+test("a closing quote then \\r that is not followed by \\n is an error", () => {
+  expect(() => run(['"a"\r', "x"])).toThrow(SyntaxError);
+  expect(() => run(['"a"\r'])).toThrow(SyntaxError);
+});
