+  try {
+    for (;;) {
+      const { done, value } = await reader.read().catch((e) => {
+        ended = true;
+        throw e;
+      });
+      if (done) {
+        ended = true;
+        break;
+      }
+      buf += dec.decode(value, { stream: true });
+      let j: number;
+      while ((j = buf.indexOf('\n')) >= 0) {
+        const raw = buf.slice(0, j);
+        const msg = line(raw.endsWith('\r') ? raw.slice(0, -1) : raw);
+        buf = buf.slice(j + 1);
+        if (msg) yield msg;
+      }
+    }
+    buf += dec.decode();
+    if (buf !== '') {
